#!/usr/bin/env bash
# SpotMicro Steam Deck app installer — build e3d0909-dirty 2026-10-15 10:40
# Run on the Deck (Desktop Mode terminal, or over ssh):  bash spotmicro-deck-setup.sh [robot-ip]
# Without a robot address it keeps the one already set (or uses 192.168.1.185 on a first install).
set -euo pipefail
TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
sed '1,/^__PAYLOAD__$/d' "$0" | base64 -d | tar -xz -C "$TMP"
HOST="${1:-$(cat "$HOME/.config/spotmicro-deck/host" 2>/dev/null || echo 192.168.1.185)}"
"$TMP/install_on_deck.sh" "$HOST"
echo "Build: $(cat "$TMP/VERSION")"
exit 0
